export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}''','''/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. A slug
 * another workspace still holds retired counts as taken.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const held = getDb()
    .select({ slug: retiredOrgSlugs.slug })
    .from(retiredOrgSlugs)
    .where(
      and(
        like(retiredOrgSlugs.slug, `${prefix}%`),
        gt(retiredOrgSlugs.retiredAt, holdCutoff()),
      ),
    )
    .all();
  return [...new Set([...rows, ...held].map((row) => row.slug))];
}

/**
 * Whether `orgId` may rename to `slug`: no other workspace, live or deleted,
 * has it as its current slug or still holds it retired. A slug the workspace
 * retired itself is always available to it.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const current = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const held = getDb()
    .select({ id: retiredOrgSlugs.id })
    .from(retiredOrgSlugs)
    .where(
      and(
        eq(retiredOrgSlugs.slug, slug),
        ne(retiredOrgSlugs.orgId, orgId),
        gt(retiredOrgSlugs.retiredAt, holdCutoff()),
      ),
    )
    .get();
  return !held;
}

/**
 * Moves the workspace to `slug` and retires the slug it replaces, as of now.
 * Taking a slug ends any retirement of it — the workspace's own, or another
 * workspace's whose hold has already run out. Only the slug column changes.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const current = tx
      .select({ slug: organizations.slug })
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    tx.delete(retiredOrgSlugs)
      .where(eq(retiredOrgSlugs.slug, slug))
      .run();
    tx.delete(retiredOrgSlugs)
      .where(eq(retiredOrgSlugs.slug, current.slug))
      .run();
    tx.insert(retiredOrgSlugs)
      .values({
        id: newId(),
        orgId,
        slug: current.slug,
        retiredAt: toIsoTimestamp(new Date()),
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

